//! Replays `fixtures/git-remote.jsonl`, generated by `rust/tools/generate_vcs_remote_fixtures.mjs`
//! from the original GitVcsDriverCore.ts and packages/shared/src/git.ts.
use serde_json::{Value, json};
use t3_vcs::{
    GitTimings,
    core::{parse_remote_names_in_git_order, sorted_longest_first},
    git::parse_git_remote_verbose_output,
    refs::parse_worktree_branch_paths,
    remote::{fetch_failure_detail, split_upstream_ref},
    remote_refs::{
        dedupe_remote_branches_with_local_matches, derive_local_branch_name_from_remote_ref,
        normalize_git_remote_url, sanitize_remote_name,
    },
    review::{parse_review_numstat, review_diff_hash},
    status_upstream_refresh_failure_cooldown,
    wire::{ReviewDiffFileStat, VcsRef},
};

fn rows(kind: &str) -> Vec<Value> {
    include_str!("fixtures/git-remote.jsonl")
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|row| row["type"] == kind)
        .collect()
}

#[test]
fn fetch_failures_are_diagnosed_from_fixed_patterns_only() {
    let rows = rows("fetchDetail");
    assert_eq!(rows.len(), 29);
    for row in rows {
        let stderr = row["stderr"].as_str().unwrap();
        assert_eq!(
            json!(fetch_failure_detail(stderr)),
            row["result"],
            "{stderr:?}"
        );
    }
}

#[test]
fn review_numstat_and_worktree_listings_match_the_original() {
    for row in rows("reviewNumstat") {
        let stdout = row["stdout"].as_str().unwrap();
        assert_eq!(
            json!(parse_review_numstat(stdout)),
            row["result"],
            "{stdout:?}"
        );
    }
    for row in rows("worktrees") {
        let stdout = row["stdout"].as_str().unwrap();
        let actual: Vec<Value> = parse_worktree_branch_paths(stdout)
            .into_iter()
            .map(|(branch, path)| json!([branch, path]))
            .collect();
        assert_eq!(Value::Array(actual), row["result"], "{stdout:?}");
    }
}

#[test]
fn remote_naming_and_url_normalization_match_the_original() {
    for row in rows("sanitizeRemote") {
        let value = row["value"].as_str().unwrap();
        assert_eq!(
            json!(sanitize_remote_name(value)),
            row["result"],
            "{value:?}"
        );
    }
    for row in rows("remoteUrl") {
        let url = row["url"].as_str().unwrap();
        assert_eq!(
            json!(normalize_git_remote_url(url)),
            row["result"],
            "{url:?}"
        );
    }
    for row in rows("upstream") {
        let names: Vec<String> = serde_json::from_value(row["names"].clone()).unwrap();
        let upstream = row["upstream"].as_str().unwrap();
        let actual = split_upstream_ref(upstream, &names).map(|split| {
            json!({"upstreamRef": split.upstream_ref, "remoteName": split.remote_name, "branchName": split.branch_name})
        });
        assert_eq!(json!(actual), row["result"], "{upstream:?}");
    }
    // `git remote -v` order of remotes is what ensureRemote walks.
    let listing = "b\thttps://x/b (fetch)\nb\thttps://x/b (push)\na\thttps://x/a (fetch)\n";
    let names: Vec<_> = parse_git_remote_verbose_output(listing)
        .into_iter()
        .map(|(name, _)| name)
        .collect();
    assert_eq!(names, ["b", "a"]);
    assert_eq!(
        sorted_longest_first(parse_remote_names_in_git_order("a\nbb\n")),
        ["bb", "a"]
    );
}

#[test]
fn ref_deduplication_matches_the_original() {
    for row in rows("sharedLocalName") {
        let name = row["name"].as_str().unwrap();
        assert_eq!(
            json!(derive_local_branch_name_from_remote_ref(name)),
            row["result"],
            "{name:?}"
        );
    }
    for row in rows("dedupe") {
        // The fixtures use `isRemote` and `remoteName` as the original's `VcsRef` has them.
        let refs: Vec<VcsRef> = serde_json::from_value(row["refs"].clone()).unwrap();
        assert_eq!(
            json!(dedupe_remote_branches_with_local_matches(&refs)),
            row["result"]
        );
    }
}

#[test]
fn diff_hashes_match_the_original() {
    let rows = rows("diffHash");
    assert_eq!(rows.len(), 5);
    for row in rows {
        let files: Vec<ReviewDiffFileStat> = serde_json::from_value(row["files"].clone()).unwrap();
        assert_eq!(
            json!(review_diff_hash(row["diff"].as_str().unwrap(), &files)),
            row["result"]
        );
    }
}

#[test]
fn the_upstream_refresh_back_off_matches_the_original() {
    let rows = rows("cooldown");
    assert_eq!(rows.len(), 41);
    for row in rows {
        let failures = row["failures"].as_u64().unwrap() as u32;
        let cooldown = status_upstream_refresh_failure_cooldown(&GitTimings::default(), failures);
        assert_eq!(
            cooldown.as_millis() as u64,
            row["ms"].as_u64().unwrap(),
            "{failures} failures"
        );
    }
}
